/* part:page.style.kit.date-picker */
/* Kit css: Date picker    kit version 0.1.0    pairs with kit/date-picker.js
   .kit-dp > .kit-dp-row (label.kit-dp-part > .kit-dp-lab + input.kit-dp-text, one or two; button.kit-dp-btn) + .kit-dp-hint + .kit-dp-pop
   .kit-dp-pop is the dialog: .kit-dp-nav (four .kit-dp-nb and the .kit-dp-head), table.kit-dp-grid, .kit-dp-presets, .kit-dp-foot.
   Days: [aria-selected="true"] chosen; .kit-dp-a and .kit-dp-b the ends of a range, .kit-dp-mid between, .kit-dp-prev while the span is being picked;
   [aria-current="date"] today (a ring), [aria-disabled="true"] not choosable (struck through). Each state has a shape or a weight, not colour alone.
   Text is --ink or --ink-2 (AA in every kit theme); --ink-3 only marks the dash and disabled days.
   Needs from the board: --panel --sunk --ink --ink-2 --ink-3 --rule --rule-2 --accent --accent-ink --accent-soft --danger --shadow --f-ui; optional --focus --radius */
.kit-dp { position: relative; display: grid; justify-items: start; gap: 4px; min-width: 0; max-width: 100%; font: 14px/1.4 var(--f-ui); color: var(--ink); }
.kit-dp-row { display: flex; flex-wrap: wrap; align-items: end; gap: 6px 8px; }
.kit-dp-part { display: grid; gap: 3px; min-width: 0; }
.kit-dp-lab { font-size: 12.5px; font-weight: 600; color: var(--ink-2); }
.kit-dp-dash { align-self: center; padding-top: 18px; color: var(--ink-3); }
.kit-dp-text { box-sizing: border-box; width: 12.5ch; min-width: 0; height: 36px; padding: 0 10px; font: inherit; font-variant-numeric: tabular-nums;
  color: var(--ink); background: var(--panel); border: 1px solid var(--rule); border-radius: var(--radius, 6px); }
.kit-dp-text::placeholder { color: var(--ink-2); opacity: 1; }
.kit-dp-text[aria-invalid="true"] { border-color: var(--danger); box-shadow: inset 0 0 0 1px var(--danger); }
.kit-dp-btn, .kit-dp-nb, .kit-dp-act, .kit-dp-pre { font: inherit; color: var(--ink); background: var(--panel); border: 1px solid var(--rule); border-radius: var(--radius, 6px); cursor: pointer; }
.kit-dp-btn { width: 36px; height: 36px; display: grid; place-items: center; padding: 0; color: var(--ink-2); }
.kit-dp-btn:hover, .kit-dp-nb:hover, .kit-dp-act:hover, .kit-dp-pre:hover { background: var(--sunk); }
.kit-dp :focus-visible { outline: 2px solid var(--focus, var(--accent)); outline-offset: 2px; }
.kit-dp-hint { justify-self: stretch; min-height: 1.4em; font-size: 12px; color: var(--ink-2); }
.kit-dp-hint.kit-dp-bad { color: var(--danger); }

.kit-dp-pop { position: absolute; z-index: 50; top: 100%; left: 0; margin-top: 4px; box-sizing: border-box; width: max-content; max-width: calc(100vw - 16px);
  display: grid; gap: 8px; padding: 10px; background: var(--panel); color: var(--ink); border: 1px solid var(--rule); border-radius: 12px; box-shadow: var(--shadow); }
.kit-dp-pop[hidden] { display: none; }
.kit-dp-pop.kit-dp-up { top: auto; bottom: 100%; margin: 0 0 4px; }
.kit-dp-pop.kit-dp-end { left: auto; right: 0; }
.kit-dp-pop:not([hidden]) { animation: kit-dp-in .12s ease-out; }
@keyframes kit-dp-in { from { opacity: 0; transform: translateY(-4px); } }
.kit-dp-nav { display: flex; align-items: center; gap: 4px; }
.kit-dp-nb { width: 32px; height: 32px; padding: 0; font-size: 18px; line-height: 1; }
.kit-dp-nb[aria-disabled="true"] { opacity: .4; cursor: default; background: var(--panel); }
.kit-dp-head { flex: 1; margin: 0; text-align: center; font: 600 15px/1.2 var(--f-ui); }
.kit-dp-grid { border-collapse: separate; border-spacing: 0 2px; }
.kit-dp-grid th { width: 38px; height: 26px; padding: 0; font-size: 12px; font-weight: 600; color: var(--ink-2); text-align: center; }
.kit-dp-grid td { width: 38px; height: 36px; padding: 0; text-align: center; border-radius: 8px; font-variant-numeric: tabular-nums; cursor: pointer; user-select: none; touch-action: manipulation; }
.kit-dp-grid td:not([data-iso]) { cursor: default; }
.kit-dp-grid td[data-iso]:hover { background: var(--sunk); }
.kit-dp-grid td[aria-current="date"] { font-weight: 700; box-shadow: inset 0 0 0 1.5px var(--ink-2); }
.kit-dp-grid td[aria-disabled="true"] { color: var(--ink-3); text-decoration: line-through; cursor: not-allowed; }
.kit-dp-grid td.kit-dp-mid { background: var(--accent-soft); color: var(--ink); border-radius: 0; }
.kit-dp-grid td.kit-dp-a { border-start-end-radius: 0; border-end-end-radius: 0; }
.kit-dp-grid td.kit-dp-b { border-start-start-radius: 0; border-end-start-radius: 0; }
.kit-dp-grid td.kit-dp-a.kit-dp-b { border-radius: 8px; }
.kit-dp-grid td[aria-selected="true"]:not(.kit-dp-mid), .kit-dp-grid td.kit-dp-a, .kit-dp-grid td.kit-dp-b { background: var(--accent); color: var(--accent-ink); font-weight: 700; }
.kit-dp-grid td.kit-dp-prev:not([aria-selected="true"]) { background: var(--accent-soft); color: var(--ink); box-shadow: inset 0 -2px 0 var(--accent); }
.kit-dp-grid td:focus-visible { outline: 2px solid var(--focus, var(--accent)); outline-offset: -2px; box-shadow: inset 0 0 0 4px var(--panel); }
.kit-dp-presets { display: flex; flex-wrap: wrap; gap: 6px; max-width: 266px; padding-top: 8px; border-top: 1px solid var(--rule-2); }
.kit-dp-pre { min-height: 30px; padding: 0 10px; font-size: 13px; background: var(--sunk); }
.kit-dp-foot { display: flex; align-items: center; gap: 6px; padding-top: 8px; border-top: 1px solid var(--rule-2); }
.kit-dp-say { flex: 1 1 0; width: 0; min-width: 0; min-height: 2.8em; display: flex; align-items: center; font-size: 12px; line-height: 1.4; color: var(--ink-2); }
.kit-dp-act { min-height: 32px; padding: 0 12px; }
.kit-dp-ok { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); font-weight: 600; }
.kit-dp-ok:hover { background: var(--accent); filter: brightness(1.08); }
@media (prefers-reduced-motion: reduce) { .kit-dp-pop:not([hidden]) { animation: none; } }
/* /part:page.style.kit.date-picker */

/**
 * Date picker
 * Kit.datePicker.mount(el, opts) builds a date field in el: a text input (two for a range), a calendar button and a calendar popover that follows the WAI-ARIA date picker dialog (a modal dialog holding a grid with roving focus). Values go in and out as ISO strings, YYYY-MM-DD; month and weekday names, the first day of the week and the typed format come from Intl for the page's locale.
 *
 * What it is: the one date field a form or a filter needs, for a single day or a range (check-in and check-out, a report window). Dates are counted in UTC from their ISO form, so a daylight saving change can never shift a day; the only local-time read is today.
 * API (small and stable):
 *   Kit.datePicker.mount(el, {mode, value, label, min, max, isDisabled, presets, locale, firstDay, strings, onChange}) -> picker
 *     mode        'single' (default) or 'range'
 *     value       single: 'YYYY-MM-DD' or null; range: {start, end}, each 'YYYY-MM-DD' or null (start after end is swapped)
 *     label       the visible label: a string, or [start, end] for a range (default 'Date', ['Start', 'End'])
 *     min, max    'YYYY-MM-DD', inclusive; isDisabled(iso) -> true strikes a day out (still reachable by keys, never chosen)
 *     presets     [{label, value}] buttons in the calendar that set a value in one press (value as above, the caller's dates)
 *     locale      BCP 47 tag (default: <html lang>, else the browser's); firstDay 0-6, Sunday 0, overrides the locale's
 *     strings     the kit's own words, English by default: choose, prevYear, prevMonth, nextMonth, nextYear, cancel, ok, pickEnd, bad, off, or
 *     onChange    (value) => void after each committed change: a day or a range picked, a preset, typed text accepted (Enter or leaving the field)
 *   picker.value() -> value as above;  picker.set(value) (no onChange);  picker.open();  picker.close();  picker.el;  picker.destroy()
 * Keys (APG): the calendar button opens the dialog on the chosen day (else today, kept within min and max). In the grid: arrows move a day or a week,
 *   Home and End the start and end of the week, Page Up and Page Down a month, with Shift a year; Enter or Space picks; Escape or Cancel closes
 *   without a change and focus goes back to the button; Tab cycles inside the dialog. A range takes two picks: the first is one end, the hover or the
 *   focused day previews the span, the second closes it (either order). Escape mid-range drops the half-picked end.
 * Typed entry: ISO (2026-11-22) or the locale's short numeric form (22/11/2026, 11/22/2026, 22.11.2026, 2026/11/22) in that locale's field order;
 *   a 2-digit year is the nearest year no more than 20 years ahead; 31/02 is rejected. Bad text stays, marked aria-invalid, and the hint says why.
 *   A range typed one end at a time may give onChange a half-set value ({start, end: null}).
 * Leaves out (the page does it): checking that a range does not span disabled days, time of day and time zones, form submission (read value()), calendars other than the Gregorian.
 *
 * @id        kit.date-picker
 * @kind      component
 * @group     Kit
 * @status    new
 * @version   0.1.0
 * @updated   2026-11-22
 * @summary   A date field with a calendar popover for one day or a range: ISO values in and out, keys as the WAI-ARIA date picker dialog, min, max and disabled days, presets, typed ISO or local dates, Intl names.
 * @tags      date, date picker, calendar, range, form, input, booking, due date, intl, locale, keyboard, aria, dialog, grid
 * @requires  none
 * @files     kit/date-picker.css, kit/samples/date-picker.json, kit/previews/date-picker.js
 * @provides  Kit.datePicker.mount
 * @config    Kit.datePicker.mount(el, opts) | mode ('single' or 'range'), value, label, min, max, isDisabled(iso), presets [{label, value}], locale, firstDay, strings, onChange(value)
 * @tokens    --panel --sunk --ink --ink-2 --ink-3 --rule --rule-2 --accent --accent-ink --accent-soft --danger --shadow --f-ui --focus? --radius?
 * @globals   none
 * @db        none
 * @preview   {"render": "kit.date-picker", "samples": ["kit/samples/date-picker.json"]}
 */
(function () {
'use strict';
const Kit = window.Kit = window.Kit || { version: '0.1.0' };
const DAY = 864e5;
const SUNDAY = 'US CA MX BR JP KR TW HK PH IL IN ZA SA PE CO VE GT HN NI PA PR DO SV BZ'.split(' ');
const WORDS = { choose: 'Choose date', prevYear: 'Previous year', prevMonth: 'Previous month', nextMonth: 'Next month', nextYear: 'Next year',
  cancel: 'Cancel', ok: 'OK', pickEnd: 'From {d}, pick the other end', bad: 'Not a date. Type', off: 'That day cannot be chosen.', or: 'or' };
let uid = 0;
const el = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt != null) e.textContent = txt; return e; };
const pad = (n, w = 2) => String(n).padStart(w, '0');
// ISO day <-> UTC milliseconds; NaN for anything that is not a real day (2026-02-31, 0099-01-01)
function ms(s) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || ''); if (!m) return NaN;
  const t = Date.UTC(+m[1], m[2] - 1, +m[3]), d = new Date(t);
  return d.getUTCFullYear() === +m[1] && d.getUTCMonth() === m[2] - 1 && d.getUTCDate() === +m[3] ? t : NaN;
}
const iso = t => { const d = new Date(t); return pad(d.getUTCFullYear(), 4) + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()); };
const valid = s => !isNaN(ms(s));
const addDays = (s, n) => iso(ms(s) + n * DAY);
function addMonths(s, n) {
  const d = new Date(ms(s)), y = d.getUTCFullYear(), m = d.getUTCMonth() + n;
  return iso(Date.UTC(y, m, Math.min(d.getUTCDate(), new Date(Date.UTC(y, m + 1, 0)).getUTCDate())));
}
const wday = s => new Date(ms(s)).getUTCDay();
const today = () => { const d = new Date(); return pad(d.getFullYear(), 4) + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); };

function locale(tag, firstDay) {
  const L = tag || document.documentElement.lang || navigator.language || 'en';
  const f = o => new Intl.DateTimeFormat(L, Object.assign({ timeZone: 'UTC', calendar: 'gregory', numberingSystem: 'latn' }, o));
  const num = f({ year: 'numeric', month: '2-digit', day: '2-digit' });
  const parts = num.formatToParts(Date.UTC(2026, 10, 22));
  const lit = parts.filter(p => p.type === 'literal').map(p => p.value).join('');
  const order = parts.filter(p => p.type === 'year' || p.type === 'month' || p.type === 'day').map(p => p.type);
  const pattern = parts.map(p => p.type === 'year' ? 'yyyy' : p.type === 'month' ? 'mm' : p.type === 'day' ? 'dd' : p.value.replace(/[‎‏]/g, '')).join('');
  let fd = 1;
  try {
    const lo = new Intl.Locale(L), wi = lo.getWeekInfo ? lo.getWeekInfo() : lo.weekInfo;
    fd = wi ? wi.firstDay % 7 : SUNDAY.includes(lo.maximize().region) ? 0 : 1;
  } catch (_) {}
  if (firstDay >= 0 && firstDay <= 6) fd = firstDay;
  const long = f({ weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  const sun = Date.UTC(2026, 10, 22);                                   // a Sunday
  const wk = ['short', 'long'].map(w => { const g = f({ weekday: w }); return [0, 1, 2, 3, 4, 5, 6].map(i => g.format(sun + i * DAY)); });
  return {
    fd, pattern, short: wk[0], longDay: wk[1],
    month: f({ month: 'long', year: 'numeric' }), long: s => long.format(ms(s)), fmt: s => s ? num.format(ms(s)) : '',
    parse(text) {
      const t = text.trim();
      if (/^\d{4}-\d{1,2}-\d{1,2}$/.test(t)) { const [y, m, d] = t.split('-'); const s = y + '-' + pad(+m) + '-' + pad(+d); return valid(s) ? s : null; }
      const n = t.match(/\d+/g); if (!n || n.length !== 3 || [...t].some(c => !/[\d\s./,-]/.test(c) && !lit.includes(c))) return null;
      const v = {}; order.forEach((k, i) => { v[k] = n[i]; });
      let y = +v.year;
      if (v.year.length <= 2) { const now = new Date().getFullYear(); y += Math.floor(now / 100) * 100; if (y > now + 20) y -= 100; }
      else if (v.year.length !== 4) return null;
      const s = pad(y, 4) + '-' + pad(+v.month) + '-' + pad(+v.day);
      return valid(s) ? s : null;
    },
  };
}

function mount(host, opts = {}) {
  const o = Object.assign({ mode: 'single', value: null, label: null, min: null, max: null, isDisabled: null, presets: [], onChange: null }, opts);
  const W = Object.assign({}, WORDS, o.strings);
  const range = o.mode === 'range', L = locale(o.locale, o.firstDay), id = 'kit-dp-' + (++uid);
  const norm = v => {
    if (!range) return valid(v) ? v : null;
    let a = v && valid(v.start) ? v.start : null, b = v && valid(v.end) ? v.end : null;
    if (a && b && a > b) [a, b] = [b, a];
    return { start: a, end: b };
  };
  const ok = s => valid(s) && !(o.min && s < o.min) && !(o.max && s > o.max) && !(o.isDisabled && o.isDisabled(s));
  const clamp = s => o.min && s < o.min ? o.min : o.max && s > o.max ? o.max : s;
  let val = norm(o.value), focus = null, anchor = null, hover = null, openNow = false;

  const root = el('div', 'kit-dp'), row = el('div', 'kit-dp-row'), hint = el('div', 'kit-dp-hint');
  hint.id = id + '-hint'; hint.setAttribute('aria-live', 'polite');
  const hintText = L.pattern + ' ' + W.or + ' yyyy-mm-dd';
  hint.textContent = hintText;
  const labels = range ? (Array.isArray(o.label) ? o.label : ['Start', 'End']) : [o.label || 'Date'];
  const ins = labels.map((t, i) => {
    const lab = el('label', 'kit-dp-part'), inp = el('input', 'kit-dp-text');
    inp.type = 'text'; inp.autocomplete = 'off'; inp.spellcheck = false; inp.placeholder = L.pattern;
    inp.setAttribute('aria-describedby', hint.id);
    lab.append(el('span', 'kit-dp-lab', t), inp); row.append(lab);
    if (range && !i) row.append(el('span', 'kit-dp-dash', '–'));
    inp.addEventListener('change', () => typed(i));
    inp.addEventListener('keydown', e => { if (e.key === 'Enter') typed(i); });
    return inp;
  });
  const btn = el('button', 'kit-dp-btn'); btn.type = 'button'; btn.setAttribute('aria-haspopup', 'dialog'); btn.setAttribute('aria-expanded', 'false');
  btn.innerHTML = '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false"><path d="M4 6.5h16v13H4zM4 10.5h16M8 4v4M16 4v4" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/></svg>';
  row.append(btn);

  const pop = el('div', 'kit-dp-pop'); pop.hidden = true;
  pop.setAttribute('role', 'dialog'); pop.setAttribute('aria-modal', 'true'); pop.setAttribute('aria-labelledby', id + '-h');
  const nav = el('div', 'kit-dp-nav'), head = el('h2', 'kit-dp-head'); head.id = id + '-h'; head.setAttribute('aria-live', 'polite');
  const navBtn = (label, glyph, step) => { const b = el('button', 'kit-dp-nb', glyph); b.type = 'button'; b.setAttribute('aria-label', label); b.dataset.step = step; return b; };
  const bPY = navBtn(W.prevYear, '«', -12), bPM = navBtn(W.prevMonth, '‹', -1), bNM = navBtn(W.nextMonth, '›', 1), bNY = navBtn(W.nextYear, '»', 12);
  nav.append(bPY, bPM, head, bNM, bNY);
  const grid = el('table', 'kit-dp-grid'); grid.setAttribute('role', 'grid'); grid.setAttribute('aria-labelledby', id + '-h');
  if (range) grid.setAttribute('aria-multiselectable', 'true');   // a range selects every day in it
  const hr = el('tr');
  for (let i = 0; i < 7; i++) { const w = (L.fd + i) % 7, th = el('th', null, L.short[w]); th.scope = 'col'; th.abbr = L.longDay[w]; hr.append(th); }
  const thead = el('thead'); thead.append(hr);
  const tbody = el('tbody'), cells = [];
  for (let r = 0; r < 6; r++) { const tr = el('tr'); for (let c = 0; c < 7; c++) { const td = el('td'); cells.push(td); tr.append(td); } tbody.append(tr); }
  grid.append(thead, tbody);
  const pre = el('div', 'kit-dp-presets');
  (o.presets || []).forEach(p => { const b = el('button', 'kit-dp-pre', p.label); b.type = 'button'; b.addEventListener('click', () => { commit(norm(p.value)); close(true); }); pre.append(b); });
  const foot = el('div', 'kit-dp-foot'), say = el('span', 'kit-dp-say'); say.setAttribute('role', 'status');
  const bCancel = el('button', 'kit-dp-act', W.cancel), bOk = el('button', 'kit-dp-act kit-dp-ok', W.ok);
  bCancel.type = bOk.type = 'button';
  foot.append(say, bCancel, bOk);
  pop.append(nav, grid);
  if (pre.childNodes.length) pop.append(pre);
  pop.append(foot);
  root.append(row, hint, pop); host.append(root);

  // what the grid shows as chosen: the committed value, or the span being picked
  function span() {
    if (!range) return [val, val];
    if (anchor) { const e = hover || focus; return anchor < e ? [anchor, e] : [e, anchor]; }
    return [val.start, val.end || val.start];
  }
  function paint() {
    const first = focus.slice(0, 8) + '01', off = (wday(first) - L.fd + 7) % 7;
    const n = new Date(Date.UTC(+focus.slice(0, 4), +focus.slice(5, 7), 0)).getUTCDate();
    const title = L.month.format(ms(first));
    if (head.textContent !== title) head.textContent = title;          // the live heading speaks only when the month changes
    const [a, b] = span(), now = today(), mk = focus.slice(0, 7);
    cells.forEach((td, i) => {
      const day = i - off + 1, s = day >= 1 && day <= n ? first.slice(0, 8) + pad(day) : null;
      td.className = ''; td.tabIndex = -1;
      ['data-iso', 'aria-label', 'aria-selected', 'aria-disabled', 'aria-current'].forEach(x => td.removeAttribute(x));
      if (!s) { td.textContent = ''; return; }
      td.textContent = day; td.dataset.iso = s; td.setAttribute('aria-label', L.long(s));
      if (s === focus) td.tabIndex = 0;
      if (!ok(s)) td.setAttribute('aria-disabled', 'true');
      if (s === now) td.setAttribute('aria-current', 'date');
      const inSpan = a && s >= a && s <= b;
      td.setAttribute('aria-selected', String(anchor ? s === anchor : !!inSpan));
      if (!inSpan || !range) return;
      td.classList.toggle('kit-dp-a', s === a); td.classList.toggle('kit-dp-b', s === b); td.classList.toggle('kit-dp-mid', s !== a && s !== b);
      td.classList.toggle('kit-dp-prev', !!anchor);
    });
    const lo = o.min && o.min.slice(0, 7) >= mk, hi = o.max && o.max.slice(0, 7) <= mk;
    [bPY, bPM].forEach(b => b.setAttribute('aria-disabled', String(!!lo)));
    [bNM, bNY].forEach(b => b.setAttribute('aria-disabled', String(!!hi)));
  }
  const cell = () => cells.find(td => td.dataset.iso === focus);
  function move(s, take) { focus = clamp(s); if (take) hover = null; paint(); if (take) cell().focus(); }
  function choose(s) {
    if (!ok(s)) { say.textContent = W.off; return; }
    if (!range) { commit(s); close(true); return; }
    if (!anchor) { anchor = s; hover = null; say.textContent = W.pickEnd.replace('{d}', L.fmt(s)); paint(); return; }
    const [a, b] = anchor < s ? [anchor, s] : [s, anchor];
    anchor = null; commit({ start: a, end: b }); close(true);
  }
  function show() {
    const v = range ? [val.start, val.end] : [val];
    ins.forEach((inp, i) => { inp.value = L.fmt(v[i]); inp.removeAttribute('aria-invalid'); });
    hint.textContent = hintText; hint.classList.remove('kit-dp-bad');
    const txt = v.filter(Boolean).map(L.long).join(' – ');
    btn.setAttribute('aria-label', W.choose + (txt ? ', ' + txt : ''));
  }
  function commit(v) { val = v; show(); if (o.onChange) o.onChange(get()); }
  const get = () => range ? { start: val.start, end: val.end } : val;
  function typed(i) {
    const inp = ins[i], t = inp.value.trim(), s = t ? L.parse(t) : null;
    const bad = msg => { inp.setAttribute('aria-invalid', 'true'); hint.textContent = msg; hint.classList.add('kit-dp-bad'); };
    if (t && !s) return bad(W.bad + ' ' + hintText + '.');
    if (s && !ok(s)) return bad(W.off);
    const cur = range ? val[i ? 'end' : 'start'] : val;
    if (s === cur) return show();
    if (!range) return commit(s);
    const n = { start: val.start, end: val.end }; n[i ? 'end' : 'start'] = s;
    commit(norm(n));
  }

  function place() {
    pop.classList.remove('kit-dp-up', 'kit-dp-end');
    const r = root.getBoundingClientRect(), p = pop.getBoundingClientRect();
